#include <iostream>
#include <optional>

enum ICmpPredicate {
  ICMP_EQ = 0,
  ICMP_NE = 1,
  ICMP_UGT = 2,
  ICMP_UGE = 3,
  ICMP_ULT = 4,
  ICMP_ULE = 5,
  ICMP_SGT = 6,
  ICMP_SGE = 7,
  ICMP_SLT = 8,
  ICMP_SLE = 9
};

class CmpPredicate {
  ICmpPredicate Pred;
  bool HasSameSign;

public:
  CmpPredicate(ICmpPredicate Pred, bool HasSameSign = false) 
    : Pred(Pred), HasSameSign(HasSameSign) {}

  static std::optional<CmpPredicate> getMatching(CmpPredicate A, CmpPredicate B) {
    if (A.Pred == B.Pred)
      return A.HasSameSign == B.HasSameSign ? A : CmpPredicate(A.Pred);

    // samesign UGT is equivalent to SGT
    if (A.HasSameSign && A.Pred == ICMP_UGT && B.Pred == ICMP_SGT)
      return B.Pred;
    if (B.HasSameSign && B.Pred == ICMP_UGT && A.Pred == ICMP_SGT)
      return A.Pred;

    // samesign UGE is equivalent to SGE  
    if (A.HasSameSign && A.Pred == ICMP_UGE && B.Pred == ICMP_SGE)
      return B.Pred;
    if (B.HasSameSign && B.Pred == ICMP_UGE && A.Pred == ICMP_SGE)
      return A.Pred;

    // samesign ULT is equivalent to SLT
    if (A.HasSameSign && A.Pred == ICMP_ULT && B.Pred == ICMP_SLT)
      return B.Pred;
    if (B.HasSameSign && B.Pred == ICMP_ULT && A.Pred == ICMP_SLT)
      return A.Pred;

    // samesign ULE is equivalent to SLE
    if (A.HasSameSign && A.Pred == ICMP_ULE && B.Pred == ICMP_SLE)
      return B.Pred;
    if (B.HasSameSign && B.Pred == ICMP_ULE && A.Pred == ICMP_SLE)
      return A.Pred;

    return {};
  }

  operator ICmpPredicate() const { return Pred; }
};

int main() {
  // Test cases
  CmpPredicate samesign_ugt(ICMP_UGT, true);
  CmpPredicate sgt(ICMP_SGT, false);
  CmpPredicate sge(ICMP_SGE, false);

  std::cout << "Testing samesign UGT vs SGT: " 
            << (CmpPredicate::getMatching(samesign_ugt, sgt).has_value() ? "MATCH" : "NO MATCH") 
            << std::endl;

  std::cout << "Testing samesign UGT vs SGE: " 
            << (CmpPredicate::getMatching(samesign_ugt, sge).has_value() ? "MATCH" : "NO MATCH") 
            << std::endl;

  // Test the condition from the patch
  bool condition1 = CmpPredicate::getMatching(samesign_ugt, sgt).has_value() ||
                    CmpPredicate::getMatching(samesign_ugt, sge).has_value();

  std::cout << "Condition (getMatching(LPred, SGT) || getMatching(LPred, SGE)): " 
            << (condition1 ? "TRUE" : "FALSE") << std::endl;

  return 0;
}
