#include <iostream>
#include <optional>

enum ICmpPredicate {
  ICMP_EQ = 0,
  ICMP_NE = 1,
  ICMP_UGT = 2,
  ICMP_UGE = 3,
  ICMP_ULT = 4,
  ICMP_ULE = 5,
  ICMP_SGT = 6,
  ICMP_SGE = 7,
  ICMP_SLT = 8,
  ICMP_SLE = 9
};

ICmpPredicate getFlippedSignednessPredicate(ICmpPredicate P) {
  // Simplified version
  switch (P) {
    case ICMP_UGT: return ICMP_SGT;
    case ICMP_UGE: return ICMP_SGE;
    case ICMP_ULT: return ICMP_SLT;
    case ICMP_ULE: return ICMP_SLE;
    case ICMP_SGT: return ICMP_UGT;
    case ICMP_SGE: return ICMP_UGE;
    case ICMP_SLT: return ICMP_ULT;
    case ICMP_SLE: return ICMP_ULE;
    default: return P;
  }
}

class CmpPredicate {
  ICmpPredicate Pred;
  bool HasSameSign;

public:
  CmpPredicate(ICmpPredicate Pred, bool HasSameSign = false) 
    : Pred(Pred), HasSameSign(HasSameSign) {}

  static std::optional<CmpPredicate> getMatching(CmpPredicate A, CmpPredicate B) {
    if (A.Pred == B.Pred)
      return A.HasSameSign == B.HasSameSign ? A : CmpPredicate(A.Pred);

    if (A.HasSameSign &&
        A.Pred == getFlippedSignednessPredicate(B.Pred))
      return B.Pred;

    if (B.HasSameSign &&
        B.Pred == getFlippedSignednessPredicate(A.Pred))
      return A.Pred;

    return {};
  }

  operator ICmpPredicate() const { return Pred; }
  bool hasSameSign() const { return HasSameSign; }
  ICmpPredicate getPred() const { return Pred; }
};

int main() {
  CmpPredicate samesign_uge(ICMP_UGE, true);
  CmpPredicate slt(ICMP_SLT, false);
  CmpPredicate sle(ICMP_SLE, false);

  auto match1 = CmpPredicate::getMatching(samesign_uge, slt);
  auto match2 = CmpPredicate::getMatching(samesign_uge, sle);

  std::cout << "getMatching(samesign UGE, SLT): " 
            << (match1.has_value() ? "MATCH" : "NO MATCH") << std::endl;

  std::cout << "getMatching(samesign UGE, SLE): " 
            << (match2.has_value() ? "MATCH" : "NO MATCH") << std::endl;

  // Also test the opposite
  CmpPredicate samesign_ule(ICMP_ULE, true);
  auto match3 = CmpPredicate::getMatching(samesign_ule, slt);
  auto match4 = CmpPredicate::getMatching(samesign_ule, sle);

  std::cout << "\ngetMatching(samesign ULE, SLT): " 
            << (match3.has_value() ? "MATCH" : "NO MATCH") << std::endl;

  std::cout << "getMatching(samesign ULE, SLE): " 
            << (match4.has_value() ? "MATCH" : "NO MATCH") << std::endl;

  return 0;
}
